SELECT     CONCAT(replace(SUBSTRING(CAST(tjzq AS VARCHAR), 5, 2), '.', ''), '月') AS month,     round(SUM(djtqje) / 10000, 2) AS hdtqje,     replace(SUBSTRING(CAST(tjzq AS VARCHAR), 5, 2), '.', '') AS month_num FROM     dws_bus_ft_per_qfq WHERE     tqlx in (83, 84, 85)     and SUBSTRING(CAST(tjzq AS VARCHAR), 1, 4) = #{ssnd} GROUP BY     CONCAT(SUBSTRING(CAST(tjzq AS VARCHAR), 5, 2), '月'),     SUBSTRING(CAST(tjzq AS VARCHAR), 5, 2) ORDER BY     month_num
